// n8n Code node (JS)
// Дістаємо текст відповіді моделі з різних можливих форматів

const src = items[0].json;

function pickText(o) {
	if (!o) return null;

	// Якщо раптом вже рядок
	if (typeof o === 'string') return o;

	// ✅ n8n "Message a model" (OpenAI Responses-style)
	// src.output[0].content = [{ type: 'output_text', text: '...' }, ...]
	const out0 = o.output?.[0];
	const t1 = out0?.content
		?.map((p) => p?.text)
		.filter(Boolean)
		.join('\n');
	if (t1) return t1;

	// Інші типові варіанти
	return (
		out0?.content?.[0]?.text ??
		out0?.text ??
		o.text ??
		// OpenAI chat.completions-like
		o.choices?.[0]?.message?.content ??
		o.choices?.[0]?.text ??
		// Gemini / Google AI Studio-like
		o.candidates?.[0]?.content?.parts?.[0]?.text ??
		o.content?.parts?.[0]?.text ??
		null
	);
}

let aiOutput = pickText(src);

if (!aiOutput) {
	throw new Error(
		'Не знайшов текстовий output від AI. Доступні ключі: ' + Object.keys(src).join(', ')
	);
}

// Якщо модель повернула не рядок, а об'єкт
if (typeof aiOutput !== 'string') aiOutput = JSON.stringify(aiOutput);

// Прибираємо можливе markdown-обгортання ```json ... ```
const clean = aiOutput
	.replace(/```(?:json)?/gi, '')
	.replace(/```/g, '')
	.trim();

// Парсимо JSON (з fallback: вирізати перший JSON-блок з тексту)
let parsed;
try {
	parsed = JSON.parse(clean);
} catch (e) {
	const m = clean.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
	if (!m) {
		throw new Error(
			'Не вдалося знайти JSON у відповіді AI. Початок відповіді: ' + clean.slice(0, 200)
		);
	}
	parsed = JSON.parse(m[1]);
}

// Нормалізуємо вихід: завжди масив items
if (!Array.isArray(parsed)) parsed = [parsed];

// Повертаємо кожен об’єкт як окремий item
return parsed.map((obj) => ({ json: obj }));

// n8n Code node (JS) — no require("crypto")
// Allowed specials: #$%&*+-,.:;!=?@[]/(){}_`~

const LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
const LOWER = "abcdefghijklmnopqrstuvwxyz";
const UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const DIGITS = "0123456789";
const SPECIAL = "#$%&*+-,.:;!=?@[]/(){}_`~";

const LENGTH = 12;
const MAX_ATTEMPTS = 2000;

// ---- RNG (prefer WebCrypto) ----
function hasWebCrypto() {
  return typeof globalThis !== "undefined"
    && globalThis.crypto
    && typeof globalThis.crypto.getRandomValues === "function";
}

function randomUint32() {
  if (hasWebCrypto()) {
    const a = new Uint32Array(1);
    globalThis.crypto.getRandomValues(a);
    return a[0] >>> 0;
  }
  // Fallback (NOT cryptographically secure)
  return (Math.floor(Math.random() * 0x100000000) >>> 0);
}

// unbiased random int in [0, maxExclusive)
function randomInt(maxExclusive) {
  if (!Number.isInteger(maxExclusive) || maxExclusive <= 0) {
    throw new Error("randomInt: maxExclusive must be a positive integer");
  }
  const maxUintPlus1 = 0x100000000; // 2^32
  const limit = Math.floor(maxUintPlus1 / maxExclusive) * maxExclusive;
  let x;
  do {
    x = randomUint32();
  } while (x >= limit);
  return x % maxExclusive;
}

function pick(str) {
  return str[randomInt(str.length)];
}

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = randomInt(i + 1);
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

// ---- similarity / forbidden checks ----
function normalizeBase(s) {
  return (s || "").toString().trim().toLowerCase();
}

function emailLocalPart(email) {
  const e = (email || "").toString().trim();
  const at = e.indexOf("@");
  return at >= 0 ? e.slice(0, at) : e;
}

function stripSeparators(s) {
  return s.replace(/[._+\- ]+/g, "");
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// leet-normalize: catch obvious variations
function leetToAlpha(s) {
  const map = {
    "0": "o",
    "1": "i",
    "2": "z",
    "3": "e",
    "4": "a",
    "5": "s",
    "6": "g",
    "7": "t",
    "8": "b",
    "9": "g",
    "@": "a",
    "$": "s",
    "!": "i",
  };
  return s
    .toLowerCase()
    .split("")
    .map((ch) => (map[ch] ? map[ch] : ch))
    .join("");
}

function buildForbiddenSignatures(username, email) {
  const u = normalizeBase(username);
  const eLocal = normalizeBase(emailLocalPart(email));

  const bases = [u, eLocal]
    .filter(Boolean)
    .map(stripSeparators)
    .filter((x) => x.length >= 3);

  const parts = [];
  for (const b of bases) {
    parts.push(b);
    // include chunks length 3..6 to prevent embedding
    for (let len = 3; len <= Math.min(6, b.length); len++) {
      for (let i = 0; i + len <= b.length; i++) {
        parts.push(b.slice(i, i + len));
      }
    }
  }

  return Array.from(new Set(parts)).filter((x) => x.length >= 3);
}

function hasRequiredClasses(pwd) {
  const hasLower = /[a-z]/.test(pwd);
  const hasUpper = /[A-Z]/.test(pwd);
  const hasDigit = /[0-9]/.test(pwd);

  // special: any char from SPECIAL
  const specialRe = new RegExp("[" + escapeRegex(SPECIAL) + "]");
  const hasSpec = specialRe.test(pwd);

  return hasLower && hasUpper && hasDigit && hasSpec;
}

function maxCommonSubstr(a, b) {
  let best = 0;
  for (let i = 0; i < a.length; i++) {
    for (let j = 0; j < b.length; j++) {
      let k = 0;
      while (i + k < a.length && j + k < b.length && a[i + k] === b[j + k]) k++;
      if (k > best) best = k;
    }
  }
  return best;
}

function looksLikeUserBasedPattern(pwd, forbidden) {
  const pwdLower = pwd.toLowerCase();
  const pwdStripped = stripSeparators(pwdLower);
  const pwdLeetNorm = stripSeparators(leetToAlpha(pwdLower));

  // block any inclusion of username/email (incl. leet-normalized)
  for (const sig of forbidden) {
    if (pwdStripped.includes(sig)) return true;
    if (pwdLeetNorm.includes(sig)) return true;
  }

  // prevent "username + digits/symbols" style (extra guard)
  const specialsOnlyRe = new RegExp("^[0-9" + escapeRegex(SPECIAL) + "]+$");
  for (const sig of forbidden) {
    if (sig.length < 4) continue;
    const re = new RegExp(escapeRegex(sig), "i");
    if (re.test(pwdStripped)) {
      const remainder = pwdStripped.replace(re, "");
      if (specialsOnlyRe.test(remainder)) return true;
    }
  }

  // visual similarity heuristic: long common substring >=4 (leet-normalized)
  const pwdAlpha = pwdLeetNorm;
  for (const sig of forbidden) {
    if (sig.length < 4) continue;
    if (maxCommonSubstr(pwdAlpha, sig) >= 4) return true;
  }

  return false;
}

function generateCandidate() {
  // Ensure at least one from each required class
  const chars = [pick(LOWER), pick(UPPER), pick(DIGITS), pick(SPECIAL)];
  const ALL = LETTERS + DIGITS + SPECIAL;

  while (chars.length < LENGTH) chars.push(pick(ALL));
  shuffle(chars);
  return chars.join("");
}

// ---- main ----
return items.map((item) => {
  const username = item.json.username ?? "";
  const email = item.json.email ?? "";

  const forbidden = buildForbiddenSignatures(username, email);

  let password = null;

  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
    const cand = generateCandidate();
    if (!hasRequiredClasses(cand)) continue;
    if (looksLikeUserBasedPattern(cand, forbidden)) continue;
    password = cand;
    break;
  }

  if (!password) {
    throw new Error(`Could not generate a compliant password after ${MAX_ATTEMPTS} attempts.`);
  }

  return {
    json: {
      ...item.json,
      password,
      rng: hasWebCrypto() ? "webcrypto" : "mathrandom_fallback",
    },
  };
});

