const src = items[0].json;

function pickText(o) {
	if (!o) return null;

	// якщо весь об'єкт уже рядок
	if (typeof o === 'string') return o;

	// якщо AI Agent повернув output як plain string
	if (typeof o.output === 'string') return o.output;

	// якщо AI Agent повернув output як object
	if (o.output && typeof o.output === 'object' && !Array.isArray(o.output)) {
		return JSON.stringify(o.output);
	}

	// n8n "Message a model" / OpenAI Responses-style
	if (Array.isArray(o.output)) {
		const out0 = o.output[0];
		const t1 = out0?.content
			?.map((p) => p?.text)
			.filter(Boolean)
			.join('\n');
		if (t1) return t1;

		if (out0?.content?.[0]?.text) return out0.content[0].text;
		if (out0?.text) return out0.text;
	}

	// інші типові варіанти
	return (
		o.text ??
		o.response ??
		o.message ??
		o.choices?.[0]?.message?.content ??
		o.choices?.[0]?.text ??
		o.candidates?.[0]?.content?.parts?.[0]?.text ??
		o.content?.parts?.[0]?.text ??
		null
	);
}

let aiOutput = pickText(src);

if (!aiOutput) {
	throw new Error(
		'Не знайшов текстовий output від AI. Доступні ключі: ' + Object.keys(src).join(', ')
	);
}

if (typeof aiOutput !== 'string') {
	aiOutput = JSON.stringify(aiOutput);
}

const clean = aiOutput
	.replace(/```(?:json)?/gi, '')
	.replace(/```/g, '')
	.trim();

let parsed;
try {
	parsed = JSON.parse(clean);
} catch (e) {
	const m = clean.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
	if (!m) {
		throw new Error(
			'Не вдалося знайти JSON у відповіді AI. Початок відповіді: ' + clean.slice(0, 200)
		);
	}
	parsed = JSON.parse(m[1]);
}

if (!Array.isArray(parsed)) parsed = [parsed];

return parsed.map((obj) => ({ json: obj }));

// Mode: Run Once for All Items

const securityItems = $input.all();

// Беремо дані з parser1
// Якщо у тебе новий синтаксис n8n не спрацює, скажу альтернативу
const parser = $('parser1').first().json;

const targetUserId = Number(parser.target_user_id);
const passwordId = Number(parser.created_password_id);

if (!targetUserId) {
	throw new Error('Не знайдено target_user_id у parser1');
}

if (!passwordId) {
	throw new Error('Не знайдено created_password_id у parser1');
}

// Будемо зберігати тільки direct user permissions,
// а inherited/project/group-права не переносимо в update.
const directPermissionsMap = new Map();

let alreadyHasAccess = false;

for (const item of securityItems) {
	const row = item.json || {};

	const userId = Number(row.user?.id || 0);
	const permissionId = Number(row.permission?.id || 0);
	const grantedVia = String(row.granted_via || '');

	// Якщо користувач уже має Read або вище — оновлення не потрібне
	if (userId === targetUserId && permissionId >= 10) {
		alreadyHasAccess = true;
	}

	// Фільтруємо лише direct password-level grants
	// Не беремо inherited/project/group grants
	const isInherited = grantedVia.includes('(Inherited)');
	const isProjectGrant = grantedVia.startsWith('Prj:');
	const isDirectPasswordGrant = !isInherited && !isProjectGrant;

	if (isDirectPasswordGrant && userId && permissionId) {
		const existing = directPermissionsMap.get(userId) || 0;
		if (permissionId > existing) {
			directPermissionsMap.set(userId, permissionId);
		}
	}
}

// Якщо користувач ще не має доступу — додаємо Read (10)
if (!alreadyHasAccess) {
	const existing = directPermissionsMap.get(targetUserId) || 0;
	if (existing < 10) {
		directPermissionsMap.set(targetUserId, 10);
	}
}

const users_permissions = Array.from(directPermissionsMap.entries()).map(
	([userId, permissionId]) => [Number(userId), Number(permissionId)]
);

return [
	{
		json: {
			password_id: passwordId,
			target_user_id: targetUserId,
			already_has_access: alreadyHasAccess,
			users_permissions,
		},
	},
];
